(()=>{let customers=[],offset=0,selected=null,loading=false,version=0;const dialog=$('#reset-customer-dialog'),form=$('#reset-customer-form');
const deleteDialog=document.createElement('dialog');deleteDialog.className='quick-category-dialog';deleteDialog.setAttribute('aria-labelledby','delete-customer-title');deleteDialog.innerHTML='<div class="dialog-head"><h2 id="delete-customer-title">حذف حساب العميل</h2><button type="button" id="close-customer-delete" aria-label="إغلاق">×</button></div><p id="delete-customer-name"></p><p>سيُغلق الحساب وتُلغى جميع جلساته، ولن يتمكن العميل من تسجيل الدخول. ستبقى طلباته ومدفوعاته محفوظة. سيظل الرقم مرتبطًا بالحساب المغلق ولا يمكن إنشاء حساب جديد به.</p><form id="delete-customer-form"><label>اكتب «حذف» لتأكيد العملية<input name="confirmation" required autocomplete="off" placeholder="حذف" maxlength="10"></label><p id="delete-customer-feedback" role="alert"></p><div class="category-manage-actions"><button type="button" id="cancel-customer-delete" class="button outline">إلغاء</button><button type="submit" class="button danger-action">تأكيد حذف الحساب</button></div></form>';document.body.append(deleteDialog);const deleteForm=deleteDialog.querySelector('form');let deleting=false,deleteTarget=null;
function closeDelete(){if(!deleting)deleteDialog.close()}
$('#close-customer-delete').onclick=closeDelete;$('#cancel-customer-delete').onclick=closeDelete;deleteDialog.addEventListener('cancel',event=>{if(deleting)event.preventDefault()});deleteDialog.addEventListener('close',()=>{deleteTarget=null;deleteForm.reset()});
document.addEventListener('click',event=>{const button=event.target.closest('[data-delete-customer]');if(!button||deleting)return;const customer=customers.find(c=>String(c.id)===button.dataset.deleteCustomer);if(!customer)return;deleteTarget=customer;deleteForm.reset();$('#delete-customer-name').textContent=customer.full_name+' — '+(customer.phone||'');$('#delete-customer-feedback').textContent='';deleteDialog.showModal();deleteForm.elements.confirmation.focus()});
deleteForm.onsubmit=async event=>{event.preventDefault();if(deleting||!deleteTarget)return;const feedback=$('#delete-customer-feedback'),button=deleteForm.querySelector('[type=submit]');if(deleteForm.elements.confirmation.value.trim()!=='حذف'){feedback.textContent='اكتب كلمة حذف لتأكيد العملية.';deleteForm.elements.confirmation.focus();return}deleting=true;button.disabled=true;feedback.textContent='جارٍ حذف الحساب…';try{await api('/api/admin/customers/'+deleteTarget.id+'/delete',{confirmation:'حذف'});deleteDialog.close();showSuccess('تم حذف حساب العميل وإلغاء جلساته، مع الاحتفاظ بطلباته السابقة.');offset=0;await loadCustomers()}catch(error){feedback.textContent=error.message}finally{deleting=false;button.disabled=false}};
async function loadCustomers(){const current=++version;$('#customers-feedback').textContent='جارٍ تحميل العملاء…';try{const data=await api('/api/admin/customers?q='+encodeURIComponent($('#customer-search').value.trim())+'&offset='+offset);if(current!==version)return;customers=data.customers;$('#customers-list').innerHTML=customers.length?customers.map(c=>`<article class="portal-row customer-row"><div><strong>${E(c.full_name)}</strong><bdi dir="ltr">${E(c.phone)}</bdi><small>${Number(c.has_password)?'لديه كلمة مرور':'حساب قديم يحتاج تعيين كلمة مرور'}</small></div><div class="category-manage-actions"><button class="button outline" type="button" data-reset-customer="${E(c.id)}">تعيين كلمة مرور</button><button class="button outline danger-action" type="button" data-delete-customer="${E(c.id)}">حذف الحساب</button></div></article>`).join(''):'<p class="admin-empty">لا يوجد عملاء مطابقون.</p>';$('#customers-prev').disabled=offset===0;$('#customers-next').disabled=!data.has_more;$('#customers-feedback').textContent=customers.length?'عرض '+(offset+1)+' إلى '+(offset+customers.length):''}catch(e){if(current===version){$('#customers-feedback').textContent=e.message;$('#customers-list').replaceChildren()}}}
async function loadVisitors(){const box=$('#visitor-totals');box.textContent='جارٍ تحميل الإحصائية…';try{const data=await api('/api/admin/visitors'),t=data.totals;box.innerHTML=[['زوار اليوم',t.today_visitors],['زوار آخر 30 يومًا',t.month_visitors],['الزوار منذ التفعيل',t.unique_visitors],['مشاهدات الصفحات',t.page_views]].map(([label,value])=>`<article><small>${E(label)}</small><strong>${E(value)}</strong></article>`).join('');const known=new Map(data.daily.map(d=>[d.day,d])),days=[];for(let n=6;n>=0;n--){const date=new Date();date.setUTCDate(date.getUTCDate()-n);const day=date.toISOString().slice(0,10);days.push(known.get(day)||{day,visitors:0,page_views:0})}const max=Math.max(1,...days.map(d=>Number(d.visitors)));$('#visitor-days').innerHTML=days.map(d=>`<div class="visitor-day"><bdi dir="ltr">${E(d.day)}</bdi><div class="visitor-bar"><span style="width:${Math.max(0,Math.min(100,Number(d.visitors)/max*100))}%"></span></div><span>${E(d.visitors)} زائر · ${E(d.page_views)} مشاهدة</span></div>`).join('')}catch(e){box.textContent=e.message;$('#visitor-days').replaceChildren()}}
document.addEventListener('click',e=>{const tab=e.target.closest('[data-tab]');if(tab?.dataset.tab==='customers')loadCustomers();if(tab?.dataset.tab==='visitors')loadVisitors();const button=e.target.closest('[data-reset-customer]');if(button){selected=customers.find(c=>String(c.id)===button.dataset.resetCustomer);if(!selected)return;form.reset();form.querySelectorAll('input').forEach(input=>input.setCustomValidity(''));form.querySelectorAll('.password-policy-note').forEach(note=>note.remove());$('#reset-customer-feedback').textContent='';$('#reset-customer-name').textContent=selected.full_name+' — '+selected.phone;dialog.showModal();form.elements.password.focus()}});
$('#customer-refresh').onclick=()=>{offset=0;loadCustomers()};$('#customer-search').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();offset=0;loadCustomers()}};$('#customers-prev').onclick=()=>{offset=Math.max(0,offset-50);loadCustomers()};$('#customers-next').onclick=()=>{offset+=50;loadCustomers()};$('#visitors-refresh').onclick=loadVisitors;
$('#close-customer-reset').onclick=()=>{if(!loading)dialog.close()};dialog.addEventListener('cancel',e=>{if(loading)e.preventDefault()});dialog.addEventListener('close',()=>{form.reset();selected=null});
form.noValidate=true;form.onsubmit=async e=>{e.preventDefault();if(loading||!selected)return;const feedback=$('#reset-customer-feedback');feedback.textContent='';const invalid=window.OwaysForms.validate(form);if(invalid){feedback.textContent=invalid;return}if(form.elements.password.value!==form.elements.password_confirmation.value){feedback.textContent='كلمتا المرور غير متطابقتين.';form.elements.password_confirmation.focus();return}loading=true;const button=form.querySelector('[type=submit]');button.disabled=true;try{await api('/api/admin/customers/'+selected.id+'/password',Object.fromEntries(new FormData(form)));dialog.close();showSuccess('تم تعيين كلمة مرور العميل وإلغاء جلساته السابقة.');await loadCustomers()}catch(error){feedback.textContent=error.message}finally{loading=false;button.disabled=false}};
})();
